// Pega a mensagem do cliente, remove espaços e divide pela vírgula.
const itensSelecionados = $items("Start")[0].json.mensagem_cliente.replace(/\s/g, '').split(',');
const itensValidos = itensSelecionados.filter(item => item && !isNaN(parseInt(item)));

if (itensValidos.length === 0) {
$json.mensagemResposta = "Por favor, envie uma lista\nde números válidos\nseparados por vírgula:\n\n_*(Exemplo: 7, 9, 15)*_\n";
$json.sql = null;
} else {
// --- INÍCIO DAS CORREÇÕES ---
// 1. Pega os dados necessários do estado atual.
const estadoAtual = $items("Start")[0].json;
const mapa = $items("cria mapa_id_json")[0].json;
const mapaId = JSON.parse(mapa.mapa_id_json) || {};
const carrinho = estadoAtual.carrinho_json || [];

// 2. Pega o primeiro item da lista que o cliente quer alterar.
const primeiroItemNumero = itensValidos[0];
const primeiroItemInfo = mapaId[primeiroItemNumero];

// 3. Validação: Verifica se o item selecionado existe no mapa.
if (!primeiroItemInfo) {
$json.mensagemResposta = `O item número ${primeiroItemNumero} não foi encontrado. Por favor, tente novamente.`;
$json.sql = null;
} else {
// 4. Encontra o item no carrinho para obter a quantidade atual.
const itemNoCarrinho = carrinho.find(item => item.id === primeiroItemInfo.id);
const quantidadeAtual = itemNoCarrinho ? itemNoCarrinho.qtd : 0; // Se não estiver no carrinho, a quantidade é 0.

const precoNumerico = primeiroItemInfo ? primeiroItemInfo.preco : 0;
const precoDoPrimeiroItem = precoNumerico.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });

const estqbase = primeiroItemInfo ? primeiroItemInfo.estq : 0;
const estq = estqbase

// 5. Monta a mensagem para o cliente.
const nomeCliente = estadoAtual.primeiro_nome;
$json.mensagemResposta = `_*${nomeCliente}*_,\nanotei os itens que você deseja alterar. 🧐\n\nQual a nova quantidade\npara o item a seguir:\n\n*${primeiroItemNumero})* `;
  if (primeiroItemInfo.nome.toLowerCase().includes('combo')) {
    $json.mensagemResposta += `📦 ${primeiroItemInfo.nome}\n\n*Preço:* ${precoDoPrimeiroItem}\n*Qtde. Atual:*\n\n----------------------------------------------------\n\nPara *REMOVER* o item\né só digitar *"0"*\n\nPara *MANTER* o item\né só digitar a mesma\n*QUANTIDADE ATUAL*\n\u200B`;
  } else {
    $json.mensagemResposta += `🍫 ${primeiroItemInfo.nome}\n\n*Preço:* ${precoDoPrimeiroItem}\n*Qtde. Atual:*\n\n----------------------------------------------------\n\nPara *REMOVER* o item\né só digitar *"0"*\n\nPara *MANTER* o item\né só digitar a mesma\n*QUANTIDADE ATUAL*\n\u200B`;
  };

// 6. Prepara o SQL para salvar a lista e mudar o estado.
$json.sql = `
    UPDATE conversas_bot
    SET
        estado_conversa = 'processando_alteracao_itens',
        itens_a_processar = '{${itensValidos.join(',')}}',
        indice_item_atual = 0,
        expirando = FALSE,
        ultima_interacao = NOW()
    WHERE jid = '${estadoAtual.Jid}'
`;

}
// --- FIM DAS CORREÇÕES ---

}
return $json;

// --- CÓDIGO PARA CONSTRUIR O MAPA_ID_JSON COMPLETO ---

// 1. Pega os dados de entrada
const todosItens = $input.all(); // Pega a lista completa do nó anterior (Notion)

// 2. Prepara a variável para o mapa
const mapaId = {};

// 3. Loop para construir o mapa de IDs.
// Itera sobre 'todosItens' (a lista completa)
for (const itemWrapper of todosItens) {
const item = itemWrapper.json;
const indiceDoItem = item.property_ndice; // Pega o índice do Notion

// Pula o item se ele não tiver um índice (é uma entrada inválida) 
if (!indiceDoItem) { continue; }

// Lógica para definir o preço (promoção ou normal) 
let precoFinalParaMapa; if (parseFloat(item.property_pre_o_promo) > 0) { precoFinalParaMapa = parseFloat(item.property_pre_o_promo); 
} else { 
precoFinalParaMapa = parseFloat(item.property_pre_o); 
}

// Salva o item no mapa usando o índice do Notion como chave. 
mapaId[indiceDoItem] = { 
id: item.property_id,
estq: item.property_estoque,
nome: item.property_nome, 
preco: precoFinalParaMapa
};

}

// 4. Prepara o resultado
// Retorna apenas o mapa e os dados de sessão necessários
const resultado = {
mapa_id_json: JSON.stringify(mapaId)
// Outros dados do 'inputParams' que você queira manter
};

return [{ json: resultado }];
